  const renderClearMarketPanel=openRoom;openRoom=function(index){renderClearMarketPanel(index);const floor=state.floors[index];if(floor?.type!=='market')return;const panel=$('workerOptions').querySelector('[data-market-panel]');if(!panel)return;const meat=floor.marketProduct==='cannedMeat',sourceStock=state.floors.filter(room=>room.type===(meat?'farm':'garden')).reduce((sum,room)=>sum+(meat?(room.farmMarketStock||0):(room.gardenMarketStock||0)),0),inputStock=meat?floor.marketMeatInputs:floor.marketVegetableInputs,finishedStock=meat?floor.stock.cannedMeat:floor.stock.cannedVegetables,productName=meat?'肉罐头':'素食罐头',sourceName=meat?'牧场专供肉':'菜园专供菜',status=!floor.workerIds.length?'未生产：请先安排超市员工':inputStock+sourceStock<=0?`等待原料：${sourceName}库存为 0`:`生产中：每名员工每 20 秒制作 1 件${productName}`;panel.className='school-section market-control-panel';panel.innerHTML=`<div class="market-active-line"><small>当前生产线</small><b>${meat?'🥩':'🥬'} ${productName}</b><span>${floor.workerIds.length} 名员工</span></div><h4>选择要生产的罐头</h4><div class="market-product-choices"><button type="button" class="${!meat?'selected':''}" data-market-product="cannedVegetables"><b>🥬 素食罐头</b><small>${!meat?'● 当前正在生产':'点击切换生产线'}</small></button><button type="button" class="${meat?'selected':''}" data-market-product="cannedMeat"><b>🥩 肉罐头</b><small>${meat?'● 当前正在生产':'点击切换生产线'}</small></button></div><div class="market-status ${floor.workerIds.length&&inputStock+sourceStock>0?'running':'waiting'}">${status}</div><h4>${productName}生产流程</h4><div class="market-flow"><span><small>① 上游专供库存</small><b>${sourceName} ${sourceStock}</b></span><i>→</i><span><small>② 超市原料</small><b>${inputStock}</b></span><i>→</i><span><small>③ 成品库存</small><b>${finishedStock}</b></span></div><div class="market-product-summary"><span><small>素食罐头</small><b>库存 ${floor.stock.cannedVegetables} · €${CANNED_PRICE} · 饱腹＋20</b></span><span><small>肉罐头</small><b>库存 ${floor.stock.cannedMeat} · €${CANNED_MEAT_PRICE} · 饱腹＋30</b></span></div><div class="market-reserve-settings"><h4>成品店内预留</h4><small>只有超过这里设置的数量，罐头才会自动对外出售。</small><label class="reserve-input-row"><span><b>素食罐头预留</b><small>当前成品 ${floor.stock.cannedVegetables}</small></span><input id="marketVegetableReserveInput" type="number" inputmode="numeric" min="0" step="1" value="${floor.marketVegetableReserve}"></label><label class="reserve-input-row"><span><b>肉罐头预留</b><small>当前成品 ${floor.stock.cannedMeat}</small></span><input id="marketMeatReserveInput" type="number" inputmode="numeric" min="0" step="1" value="${floor.marketMeatReserve}"></label><button class="reserve-save" id="saveMarketReserves" type="button">保存成品预留</button></div>`;panel.querySelectorAll('[data-market-product]').forEach(button=>button.onclick=()=>setMarketProduct(button.dataset.marketProduct));$('saveMarketReserves').onclick=()=>setMarketReserves($('marketVegetableReserveInput').value,$('marketMeatReserveInput').value)}
  function setBookReserve(value){const floor=state.floors[activeRoomIndex];if(floor?.type!=='bookstore')return;floor.bookReserve=Math.max(0,Math.floor(Number(value)||0));const sold=Math.max(0,floor.bookStock-floor.bookReserve);if(sold){floor.bookStock-=sold;splitRoomIncome(floor,sold*BOOK_PRICE)}save();render();openRoom(activeRoomIndex);toast(sold?`对外售出 ${sold} 本书，收入 ${euro(sold*BOOK_PRICE)}`:`书店预留数量改为 ${floor.bookReserve}`)}
  function setMarketReserves(vegetableValue,meatValue){const floor=state.floors[activeRoomIndex];if(floor?.type!=='market')return;floor.marketVegetableReserve=Math.max(0,Math.floor(Number(vegetableValue)||0));floor.marketMeatReserve=Math.max(0,Math.floor(Number(meatValue)||0));const sold=sellMarketSurplus(floor);syncInventory();save();render();openRoom(activeRoomIndex);toast(`超市预留已更新：素食 ${floor.marketVegetableReserve} 件，肉类 ${floor.marketMeatReserve} 件${sold?`，自动售出 ${sold} 件`:''}`)}
  function toggleGamePlayer(id){const floor=state.floors[activeRoomIndex],person=residentById(id);if(floor?.type!=='game'||!person)return;floor.playerIds=floor.playerIds||[];floor.gameStartedAt=floor.gameStartedAt||{};const selected=floor.playerIds.includes(id);if(selected){floor.playerIds=floor.playerIds.filter(personId=>personId!==id);delete floor.gameStartedAt[id]}else{if(!floor.workerIds.length)return toast('游戏房至少需要 1 名员工才能营业');if(floor.playerIds.length>=3)return toast('游戏房最多同时接待 3 名顾客');if(spendableMoney(person)<20)return toast(`${person.name} 的${walletLabel(person)}不足 €20`);removePersonAssignments(id,floor);floor.playerIds.push(id);floor.gameStartedAt[id]=simulationNow()}save();render();openRoom(activeRoomIndex);toast(selected?`${person.name} 离开了游戏房`:`${person.name} 开始游玩，1 天后结算`)}
  const renderGamePeople=render;render=function(){renderGamePeople();state.floors.forEach((floor,index)=>{if(floor.type!=='game')return;const article=document.querySelector(`[data-room="${index}"]`),body=article?.querySelector('.floor-body'),players=(floor.playerIds||[]).map(residentById).filter(Boolean);if(!article||!body)return;article.querySelector('.floor-head span').textContent=`员工 ${floor.workerIds.length}/1 · 玩家 ${players.length}/3`;players.forEach(player=>{body.insertAdjacentHTML('beforeend',personButton(player));const buttons=body.querySelectorAll(`[data-person="${player.id}"]`),button=buttons[buttons.length-1];if(button)button.onclick=event=>{event.stopPropagation();openPerson(player.id);$('sheetMeta').textContent+=` · 正在 F${index+1} 游戏房游玩`;renderServiceChoices(player)}})})}
  const renderBookstoreFloors=render;render=function(){renderBookstoreFloors();state.floors.forEach((floor,index)=>{const article=document.querySelector(`[data-room="${index}"]`),body=article?.querySelector('.floor-body');if(!article||!body)return;if(floor.type==='bookstore'){const active=floor.workerIds.length>0,elapsed=active&&floor.cycleStartedAt?simulationNow()-floor.cycleStartedAt:0;article.querySelector('.floor-head span').textContent=`员工 ${floor.workerIds.length}/2 · 库存 ${floor.bookStock||0} · 预留 ${floor.bookReserve||0}`;body.insertAdjacentHTML('beforeend',`<div class="production-ui"><div class="production-label"><span>📚 每人每天 1 本</span><span class="production-time">${active?Math.max(0,Math.ceil((DAY_MS-elapsed%DAY_MS)/1000))+'s':'待命'}</span></div><div class="production-track"><i class="production-fill" style="width:${active?Math.min(100,(elapsed%DAY_MS)/DAY_MS*100):0}%"></i></div></div>`)}if(isPrivateHome(floor)&&(floor.bookStock||0)>0)body.insertAdjacentHTML('beforeend',`<span class="home-books" title="家庭藏书">📚 ${floor.bookStock}</span>`)})}
  function setMarketProduct(product){const floor=state.floors[activeRoomIndex];if(floor?.type!=='market'||!['cannedVegetables','cannedMeat'].includes(product))return;floor.marketProduct=product;floor.cycleStartedAt=floor.workerIds.length?simulationNow():null;save();render();openRoom(activeRoomIndex);toast(`超市改为生产${product==='cannedMeat'?'肉罐头':'素食罐头'}`)}
  function setGardenReserves(directValue,marketValue){const floor=state.floors[activeRoomIndex];if(floor?.type!=='garden')return;const direct=Math.max(0,Math.floor(Number(directValue)||0)),market=Math.max(0,Math.floor(Number(marketValue)||0));floor.gardenDirectReserve=direct;floor.gardenMarketReserve=market;const sold=balanceGardenStock(floor);syncInventory();save();render();openRoom(activeRoomIndex);toast(`菜园预留已更新：直食 ${direct} 件，超市 ${market} 件${sold?`，自动售出 ${sold} 件`:''}`)}
  function setFarmReserves(directValue,marketValue){const floor=state.floors[activeRoomIndex];if(floor?.type!=='farm')return;floor.farmDirectReserve=Math.max(0,Math.floor(Number(directValue)||0));floor.farmMarketReserve=Math.max(0,Math.floor(Number(marketValue)||0));const sold=balanceFarmStock(floor);syncInventory();save();render();openRoom(activeRoomIndex);toast(`牧场预留已更新：直食 ${floor.farmDirectReserve} 件，超市 ${floor.farmMarketReserve} 件${sold?`，自动售出 ${sold} 件`:''}`)}
