  function renderClock(now=simulationNow()){const elapsed=Math.max(0,now-state.createdAt),totalDay=Math.floor(elapsed/DAY_MS),year=Math.floor(totalDay/DAYS_PER_YEAR)+1,day=totalDay%DAYS_PER_YEAR+1,dayProgress=(elapsed%DAY_MS)/DAY_MS,totalMinutes=Math.floor(dayProgress*1440),hours=String(Math.floor(totalMinutes/60)).padStart(2,'0'),minutes=String(totalMinutes%60).padStart(2,'0');$('gameClock').textContent=`第${year}年第${day}天 ${hours}:${minutes}`}
