  function splitRoomIncome(floor,amount){const workers=floor.workerIds.map(residentById).filter(Boolean),staffShare=amount/2;if(workers.length){const share=staffShare/workers.length;workers.forEach(worker=>worker.money=Math.round(((worker.money||0)+share)*1000)/1000)}state.money=Math.round((state.money+amount/2)*1000)/1000}
