  async function aiRunGeneration(repeat=true){if(!aiTraining.running)return;const token=aiLoopToken,generation=aiTraining.generation+1,base=aiTraining.population.length?aiTraining.population:Array.from({length:AI_POPULATION},aiRandomGenome),results=[];for(let index=0;index<base.length;index++){if(!aiTraining.running||token!==aiLoopToken)return;const genome=base[index],trials=AI_EVAL_SEEDS.slice(0,AI_TEST_WORLDS).map(seed=>aiSimulateRealistic(genome,seed)),average=key=>trials.reduce((sum,item)=>sum+item[key],0)/trials.length;results.push({genome,result:{fitness:average('fitness'),days:average('days'),population:average('population'),births:average('births'),deaths:average('deaths'),starvationDeaths:average('starvationDeaths'),satisfaction:average('satisfaction'),money:average('money')}});await new Promise(resolve=>setTimeout(resolve,0))}if(!aiTraining.running||token!==aiLoopToken)return;results.sort((a,b)=>b.result.fitness-a.result.fitness);const winner=results[0];aiTraining.generation=generation;if(!aiTraining.best||winner.result.fitness>aiTraining.best.result.fitness){aiTraining.best=winner;aiTraining.logs.unshift({stamp:`第${generation}代`,message:`刷新纪录：存活 ${Math.round(winner.result.days)} 天，出生 ${winner.result.births.toFixed(1)} 人，满意 ${winner.result.satisfaction.toFixed(0)}`})}const elites=results.slice(0,Math.max(4,Math.floor(AI_POPULATION*.2))).map(item=>item.genome);aiTraining.population=[...elites];while(aiTraining.population.length<AI_POPULATION)aiTraining.population.push(aiMutateGenome(random(elites)));aiTraining.logs=aiTraining.logs.slice(0,80);aiSaveTraining();renderAITraining();if(repeat)setTimeout(()=>{if(token===aiLoopToken)aiRunGeneration()},30)}
  async function aiRunGeneration(repeat=true){
    if(!aiTraining.running)return;
    const token=aiLoopToken,generation=aiTraining.generation+1,base=aiTraining.population.length?aiTraining.population:Array.from({length:AI_POPULATION},aiRandomGenome),results=[];
    for(const genome of base){
      if(!aiTraining.running||token!==aiLoopToken)return;
      const trials=AI_EVAL_SEEDS.map(seed=>aiSimulateRealistic(genome,seed)),average=key=>trials.reduce((sum,item)=>sum+item[key],0)/trials.length;
      results.push({genome,result:{fitness:average('fitness'),days:average('days'),population:average('population'),births:average('births'),adultDescendants:average('adultDescendants'),deaths:average('deaths'),starvationDeaths:average('starvationDeaths'),lineageGeneration:average('lineageGeneration'),satisfaction:average('satisfaction'),money:average('money')}});
      await new Promise(resolve=>setTimeout(resolve,0));
    }
    if(!aiTraining.running||token!==aiLoopToken)return;
    results.sort((a,b)=>b.result.fitness-a.result.fitness);const winner=results[0],previousFitness=aiTraining.best?.result?.fitness??-Infinity,improved=winner.result.fitness>previousFitness,average=key=>results.reduce((sum,item)=>sum+item.result[key],0)/results.length;aiTraining.generation=generation;
    if(improved){aiTraining.best=winner;aiTraining.logs.unshift({stamp:`第${generation}代`,message:`综合评分刷新：${Math.round(winner.result.days)}天 · 最终${winner.result.population.toFixed(1)}人 · 出生${winner.result.births.toFixed(1)} · 死亡${winner.result.deaths.toFixed(1)}`})}
    aiTraining.history.unshift({generation,improved,winnerFitness:winner.result.fitness,winnerDays:winner.result.days,winnerPopulation:winner.result.population,winnerBirths:winner.result.births,winnerAdultDescendants:winner.result.adultDescendants,winnerDeaths:winner.result.deaths,winnerStarvationDeaths:winner.result.starvationDeaths,winnerLineageGeneration:winner.result.lineageGeneration,winnerSatisfaction:winner.result.satisfaction,averageFitness:average('fitness'),averageDays:average('days'),averagePopulation:average('population'),averageBirths:average('births'),averageAdultDescendants:average('adultDescendants'),averageDeaths:average('deaths'),averageStarvationDeaths:average('starvationDeaths'),averageLineageGeneration:average('lineageGeneration')});aiTraining.history=aiTraining.history.slice(0,120);
    const elites=results.slice(0,Math.max(4,Math.floor(AI_POPULATION*.2))).map(item=>item.genome);aiTraining.population=[...elites];while(aiTraining.population.length<AI_POPULATION)aiTraining.population.push(Math.random()<.15?aiRandomGenome():aiMutateGenome(random(elites)));aiTraining.logs=aiTraining.logs.slice(0,80);aiSaveTraining();renderAITraining();if(repeat)setTimeout(()=>{if(token===aiLoopToken)aiRunGeneration()},30)
  }
  function startAITraining(){if(aiTraining.running)return;aiTraining.running=true;aiLoopToken++;aiLog('开始高速模拟；正常游戏仍会继续运行');aiRunGeneration()}
  function pauseAITraining(){if(!aiTraining.running)return;aiTraining.running=false;aiLoopToken++;aiSaveTraining();aiLog('训练已暂停');renderAITraining()}
  function resetAITraining(){if(!window.confirm('确定清除所有本地AI训练代数和最佳策略吗？正常游戏存档不会受影响。'))return;aiTraining={version:20,running:false,takeover:false,generation:0,best:null,population:[],logs:[],history:[],ignorePublished:true};aiLoopToken++;aiSaveTraining();renderAITraining()}
  function renderAIQuickButton(){const button=$('quickAI');if(!button)return;button.classList.toggle('active',aiTraining.takeover);button.textContent=aiTraining.takeover?'■ 停止AI':'AI 托管';button.setAttribute('aria-pressed',String(aiTraining.takeover))}
  function toggleAITakeover(){if(!activeAIBest())return toast('暂时没有可用的AI策略');aiTraining.takeover=!aiTraining.takeover;aiSaveTraining();aiLog(aiTraining.takeover?'最佳策略开始接管当前大楼':'AI已停止接管，恢复手动操作');renderAIQuickButton();if(aiTraining.takeover)aiLiveDecision()}
