  function renderAITraining(){const panel=$('aiTrainingPanel');if(!panel)return;const best=aiTraining.best,genome=best?.genome,result=best?.result;panel.innerHTML=`<div class="ai-hero"><small>${aiTraining.running?'正在高速训练':'训练已暂停'}</small><b>${best?`最佳存活 ${Math.round(result.days)} 天`:'尚无训练结果'}</b><span>目标顺序：避免灭绝 → 延续世代 → 提高满意度 → 增加资产</span></div><div class="ai-controls"><button id="aiTrainToggle" class="primary" type="button">${aiTraining.running?'暂停训练':'开始／继续训练'}</button><button id="aiTakeover" type="button" ${best?'':'disabled'}>${aiTraining.takeover?'停止接管':'最佳AI接管游戏'}</button><button id="aiSingleGeneration" type="button" ${aiTraining.running?'disabled':''}>只训练一代</button><button id="aiReset" type="button">清除训练</button></div><div class="ai-metrics"><span><small>训练代数</small><b>${aiTraining.generation}</b></span><span><small>最终人口</small><b>${result?result.population.toFixed(1):'—'}</b></span><span><small>累计出生</small><b>${result?result.births.toFixed(1):'—'}</b></span><span><small>平均满意</small><b>${result?result.satisfaction.toFixed(0):'—'}</b></span><span><small>最终资产</small><b>${result?euro(result.money):'—'}</b></span><span><small>饥饿死亡</small><b>${result?result.starvationDeaths.toFixed(1):'—'}</b></span></div>${genome?`<div class="ai-policy"><h3>当前最佳策略基因</h3><div class="ai-policy-grid"><span><small>食物安全库存</small><b>${genome.foodBuffer}份／人</b></span><span><small>菜园承载目标</small><b>${genome.gardenCapacity}人／间</b></span><span><small>牧场资金阈值</small><b>${euro(genome.farmThreshold)}</b></span><span><small>超市资金阈值</small><b>${euro(genome.marketThreshold)}</b></span><span><small>医疗资金阈值</small><b>${euro(genome.clinicThreshold)}</b></span><span><small>目标人口</small><b>${genome.birthTarget}人</b></span></div></div>`:''}<div class="ai-log-card"><h3>训练与接管记录</h3><div class="ai-log">${aiTraining.logs.length?aiTraining.logs.map(entry=>`<p><time>${entry.stamp}</time><span>${entry.message}</span></p>`).join(''):'<p class="ai-empty">开始训练后，这里会记录策略进化过程。</p>'}</div></div>`;$('aiTrainToggle').onclick=aiTraining.running?pauseAITraining:startAITraining;$('aiTakeover').onclick=toggleAITakeover;$('aiSingleGeneration').onclick=()=>{aiTraining.running=true;aiLoopToken++;const token=aiLoopToken;aiRunGeneration();setTimeout(()=>{if(token===aiLoopToken)pauseAITraining()},10)};$('aiReset').onclick=resetAITraining}
  function aiAddRoom(type){const room=ROOMS[type];if(!room||room.buildable===false||state.money<room.cost)return false;state.money-=room.cost;state.floors.push({id:floorId(state.floors.length),type,residents:[],ownerId:null,workerIds:[],playerIds:[],gameStartedAt:{},mayorId:null,cycleStartedAt:null,teacherId:null,studentIds:[],taughtSkill:null,schoolStartedAt:null,barberId:null,barberQueue:[],currentClientId:null,barberStartedAt:null,maternityFamilyIds:[],clothingStock:0,clothingReserve:2,bookStock:0,bookReserve:2,gardenDirectReserve:3,gardenMarketReserve:3,gardenMarketStock:0,farmDirectReserve:3,farmMarketReserve:3,farmMarketStock:0,farmMilkReserve:3,marketVegetableReserve:3,marketMeatReserve:3,marketVegetableInputs:0,marketMeatInputs:0,marketProduct:'cannedVegetables',stock:{vegetables:0,cannedVegetables:0,cannedMeat:0,meat:0,milk:0}});aiLog(`建造 F${state.floors.length} ${room.name}`);return true}
  function aiFillWorkers(floor){const capacity=roomCapacity(floor);floor.workerIds=(floor.workerIds||[]).filter(id=>{const person=residentById(id);return person&&!person.sick&&person.age>16&&meetsWorkerSkill(person,floor)});while(floor.workerIds.length<capacity){const candidate=state.people.filter(person=>person.age>16&&!person.sick&&!workerFloor(person.id)&&meetsWorkerSkill(person,floor)).sort((a,b)=>(b.skills[floor.type==='market'?'物流':floor.type==='garden'||floor.type==='farm'?'食品':'服务']||0)-(a.skills[floor.type==='market'?'物流':floor.type==='garden'||floor.type==='farm'?'食品':'服务']||0))[0];if(!candidate)break;removePersonAssignments(candidate.id,floor);floor.workerIds.push(candidate.id);floor.cycleStartedAt=simulationNow();aiLog(`安排 ${candidate.name} 到${ROOMS[floor.type].name}工作`)}}
  function aiLiveDecision(){if(!aiTraining.takeover||!aiTraining.best||Number.isFinite(state.pausedAt))return;const genome=aiTraining.best.genome;if(!state.people.length){aiTraining.takeover=false;aiSaveTraining();renderAIQuickButton();return aiLog('所有居民已经去世，本局游戏结束')}const city=state.floors.find(floor=>floor.type==='cityhall');if(city&&!city.mayorId){const candidate=state.people.filter(person=>person.age>16&&!person.sick&&!workerFloor(person.id)).sort((a,b)=>Math.max(...SKILLS.map(skill=>a.skills[skill]||0))-Math.max(...SKILLS.map(skill=>b.skills[skill]||0)))[0];if(candidate){city.mayorId=candidate.id;aiLog(`任命 ${candidate.name} 为市长`)}}let gardens=state.floors.filter(floor=>floor.type==='garden');const targetGardens=Math.max(1,Math.ceil(state.people.length/genome.gardenCapacity));if(gardens.length<targetGardens&&state.money>=ROOMS.garden.cost){aiAddRoom('garden');gardens=state.floors.filter(floor=>floor.type==='garden')}if(!state.floors.some(floor=>floor.type==='farm')&&state.money>=genome.farmThreshold)aiAddRoom('farm');if(!state.floors.some(floor=>floor.type==='market')&&state.money>=genome.marketThreshold)aiAddRoom('market');if(state.people.some(person=>person.sick)&&!state.floors.some(floor=>floor.type==='clinic')&&state.money>=genome.clinicThreshold)aiAddRoom('clinic');if(state.people.some(person=>person.pregnancy)&&!state.floors.some(floor=>floor.type==='maternity')&&state.money>=genome.maternityThreshold)aiAddRoom('maternity');state.floors.filter(floor=>['garden','farm','market','clinic','maternity'].includes(floor.type)).forEach(aiFillWorkers);state.floors.filter(floor=>floor.type==='garden').forEach(floor=>{floor.gardenDirectReserve=Math.ceil(state.people.length*genome.foodBuffer);floor.gardenMarketReserve=Math.ceil(state.people.length*Math.max(1,genome.foodBuffer/2))});state.floors.filter(floor=>floor.type==='farm').forEach(floor=>{floor.farmDirectReserve=Math.ceil(state.people.length*Math.max(1,genome.foodBuffer/2));floor.farmMarketReserve=Math.ceil(state.people.length*Math.max(1,genome.foodBuffer/2));floor.farmMilkReserve=Math.ceil(state.people.length/2)});state.floors.filter(floor=>floor.type==='market').forEach(floor=>{const meat=state.floors.reduce((sum,room)=>sum+(room.farmMarketStock||0),0)>state.floors.reduce((sum,room)=>sum+(room.gardenMarketStock||0),0);floor.marketProduct=meat?'cannedMeat':'cannedVegetables';floor.marketVegetableReserve=Math.ceil(state.people.length);floor.marketMeatReserve=Math.ceil(state.people.length)});state.people.forEach(person=>{person.foodPreference='auto';if(spendableMoney(person)<MILK_PRICE)person.milkPreference='none'});save();render();renderAITraining();renderAIQuickButton()}
  async function saveAIPolicyFile(){if(!aiTraining.best||aiTraining.best.published)return toast('请先在本机训练出新的最佳策略');const best={...aiTraining.best};delete best.published;const policy={version:1,trainingVersion:20,publishedAt:new Date().toISOString(),generation:aiTraining.generation,source:'local-evolution-training',best};try{const response=await fetch('/api/ai-policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(policy)});if(!response.ok)throw Error(response.status);publishedAI=policy;aiTraining.best.published=true;aiSaveTraining();aiLog(`第 ${aiTraining.generation} 代最佳策略已直接写入 ai-policy.json`);renderAITraining()}catch(error){toast('无法写入策略文件：请使用 node server.js 启动本地训练服务器')}}
  function aiReportNumber(value,digits=1){return Number.isFinite(value)?Number(value).toFixed(digits):'—'}
  function buildAITrainingReport(){const best=aiTraining.best?.result,genome=aiTraining.best?.genome,history=(aiTraining.history||[]).slice(0,20).reverse(),lines=['# AI训练诊断','',`- 训练版本：V${aiTraining.version}` ,`- 当前代数：${aiTraining.generation}`,`- 策略基因：${AI_GENE_COUNT}；候选策略：${AI_POPULATION}/代；固定世界：${AI_TEST_WORLDS}；测试长度：${AI_HORIZON_DAYS}天`,`- 当前最佳：${best?`${Math.round(best.days)}天，最终${aiReportNumber(best.population)}人，延续${aiReportNumber(best.lineageGeneration)}代，成年后代${aiReportNumber(best.adultDescendants)}人，出生${aiReportNumber(best.births)}，死亡${aiReportNumber(best.deaths)}，饥饿死亡${aiReportNumber(best.starvationDeaths)}，满意${aiReportNumber(best.satisfaction)}`:'无'}`,`- 最佳基因：${genome?JSON.stringify(genome):'无'}`,'','| 代数 | 破纪录 | 冠军天数 | 冠军人口 | 延续世代 | 成年后代 | 冠军出生 | 冠军死亡 | 饥饿死亡 | 满意度 | 平均天数 | 平均人口 | 平均世代 | 平均成年后代 | 平均出生 | 平均死亡 | 平均饥饿死亡 |','|---:|:---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|'];history.forEach(row=>lines.push(`| ${row.generation} | ${row.improved?'是':'否'} | ${Math.round(row.winnerDays)} | ${aiReportNumber(row.winnerPopulation)} | ${aiReportNumber(row.winnerLineageGeneration)} | ${aiReportNumber(row.winnerAdultDescendants)} | ${aiReportNumber(row.winnerBirths)} | ${aiReportNumber(row.winnerDeaths)} | ${aiReportNumber(row.winnerStarvationDeaths)} | ${aiReportNumber(row.winnerSatisfaction)} | ${Math.round(row.averageDays)} | ${aiReportNumber(row.averagePopulation)} | ${aiReportNumber(row.averageLineageGeneration)} | ${aiReportNumber(row.averageAdultDescendants)} | ${aiReportNumber(row.averageBirths)} | ${aiReportNumber(row.averageDeaths)} | ${aiReportNumber(row.averageStarvationDeaths)} |`));return lines.join('\n')}
  async function copyAITrainingReport(){const report=buildAITrainingReport();try{await navigator.clipboard.writeText(report)}catch{const area=document.createElement('textarea');area.value=report;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}toast('训练诊断表已复制，可以直接粘贴给我')}
  const renderAIPublishing=renderAITraining;renderAITraining=function(){renderAIPublishing();const panel=$('aiTrainingPanel'),controls=panel?.querySelector('.ai-controls');if(!controls)return;const isPublishedOnly=Boolean(aiTraining.best?.published),localServer=['localhost','127.0.0.1'].includes(location.hostname);controls.insertAdjacentHTML('beforeend',`<button id="aiExport" type="button" ${!aiTraining.best||isPublishedOnly||!localServer?'disabled':''}>保存到策略文件</button>`);$('aiExport').onclick=saveAIPolicyFile;const hero=panel.querySelector('.ai-hero small');if(hero&&!aiTraining.running)hero.textContent=isPublishedOnly?'已加载／保存发布策略':'使用本机训练策略'}
  const renderAIOutcome=renderAITraining;renderAITraining=function(){renderAIOutcome();const result=aiTraining.best?.result,panel=$('aiTrainingPanel'),label=panel?.querySelector('.ai-hero b'),target=panel?.querySelector('.ai-hero span');if(target)target.textContent='目标顺序：避免灭绝 → 最终人口净增长 → 持续出生 → 满意度与资产';if(!result||!label)return;if(result.population<=0)label.textContent=`当前最佳仍会灭绝 · ${Math.round(result.days)} 天`;else if(result.days>=AI_HORIZON_DAYS)label.textContent=`通过 ${AI_HORIZON_DAYS} 天测试 · 最终 ${result.population.toFixed(1)} 人`;else label.textContent=`存活 ${Math.round(result.days)} 天 · 最终 ${result.population.toFixed(1)} 人`}
  const renderAICompactLog=renderAITraining;renderAITraining=function(){renderAICompactLog();const panel=$('aiTrainingPanel'),card=panel?.querySelector('.ai-log-card'),metrics=panel?.querySelector('.ai-metrics'),entries=card?[...card.querySelectorAll('.ai-log p:not(.ai-empty)')]:[];if(!card||!metrics)return;metrics.after(card);const shown=6;entries.slice(shown).forEach(entry=>entry.remove());const heading=card.querySelector('h3');if(heading)heading.innerHTML=`关键进展 <small>最近 ${Math.min(shown,entries.length)} 条${aiTraining.logs.length>shown?` · 已省略 ${aiTraining.logs.length-shown} 条`:''}</small>`}
  const renderAIBatches=renderAITraining;renderAITraining=function(){renderAIBatches();const panel=$('aiTrainingPanel'),controls=panel?.querySelector('.ai-controls'),metrics=panel?.querySelector('.ai-metrics'),history=aiTraining.history||[];if(!panel||!controls||!metrics)return;controls.insertAdjacentHTML('afterend',`<section class="ai-parameters"><b>遗传算法参数</b><span>每代 ${AI_POPULATION} 个策略</span><span>${AI_TEST_WORLDS} 个固定世界</span><span>精英保留 20%</span><span>单基因突变率 38%</span><span>测试 ${AI_HORIZON_DAYS} 天</span></section>`);const rows=history.slice(0,10).map(batch=>`<div class="ai-batch-row ${batch.improved?'improved':''}"><b>第 ${batch.generation} 代${batch.improved?' ↑':''}</b><span>冠军 ${Math.round(batch.winnerDays)}天 / ${batch.winnerPopulation.toFixed(1)}人 / 出生${batch.winnerBirths.toFixed(1)}</span><small>本代平均 ${Math.round(batch.averageDays)}天 / ${batch.averagePopulation.toFixed(1)}人 / 出生${batch.averageBirths.toFixed(1)}</small></div>`).join('');metrics.insertAdjacentHTML('afterend',`<section class="ai-batches"><header><b>每代批次结果</b><small>${aiTraining.running?'实时更新中':'训练已暂停'} · 最近 ${Math.min(10,history.length)} 代</small></header>${rows||'<div class="ai-batch-empty">开始训练后，每一代都会显示在这里。</div>'}</section>`)}
  const renderAIReportButton=renderAITraining;renderAITraining=function(){renderAIReportButton();const parameters=$('aiTrainingPanel')?.querySelector('.ai-parameters');if(!parameters)return;parameters.insertAdjacentHTML('beforeend',`<button id="copyAIReport" type="button" ${aiTraining.history?.length?'':'disabled'}>复制训练诊断表</button>`);$('copyAIReport').onclick=copyAITrainingReport}
  const renderAIStrategyCount=renderAITraining;renderAITraining=function(){renderAIStrategyCount();const parameters=$('aiTrainingPanel')?.querySelector('.ai-parameters');if(!parameters)return;const title=parameters.querySelector('b');if(title)title.textContent=`遗传算法 · ${AI_GENE_COUNT} 项策略参数`;parameters.querySelector('span')?.replaceChildren(document.createTextNode(`每代 ${AI_POPULATION} 个候选策略`))}
