  activeAIBest=function(){return aiTraining.best||publishedAI?.best||null};
  loadPublishedAI=async function(){try{const response=await fetch(`${AI_POLICY_URL}?v=${encodeURIComponent(VERSION)}&t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error(response.status);const policy=await response.json();if(policy?.version!==2||policy.trainingVersion!==25||!LEARN.valid(policy.best?.policy))throw Error('legacy policy');publishedAI=policy;if(!aiTraining.best&&!aiTraining.ignorePublished)aiTraining.best={...policy.best,published:true};renderAITraining();renderAIQuickButton()}catch(error){console.debug('V25线上策略暂时不可用',error)}};
  function v21Average(trials,key){return trials.reduce((sum,item)=>sum+item[key],0)/trials.length}
  let v24Worker=null,v24WorkerReject=null,v24RequestId=0;
  function v24StopWorker(){if(v24WorkerReject)v24WorkerReject(Error('training paused'));v24WorkerReject=null;if(v24Worker)v24Worker.terminate();v24Worker=null}
  function v24Evaluate(policy,token){return new Promise((resolve,reject)=>{if(!aiTraining.running||token!==aiLoopToken)return reject(Error('training paused'));if(!v24Worker)v24Worker=new Worker(`ai-worker.js?v=${encodeURIComponent(VERSION)}`);const id=++v24RequestId;v24WorkerReject=reject;v24Worker.onmessage=event=>{if(event.data?.id!==id)return;v24WorkerReject=null;if(event.data.error)reject(Error(event.data.error));else resolve(event.data.trials)};v24Worker.onerror=event=>{v24WorkerReject=null;reject(Error(event.message||'worker failed'))};v24Worker.postMessage({id,policy,seeds:AI_EVAL_SEEDS,horizon:AI_HORIZON_DAYS})})}
  aiRunGeneration=async function(repeat=true){if(!aiTraining.running)return;const token=aiLoopToken,generation=aiTraining.generation+1,rand=Math.random,base=aiTraining.population.length?aiTraining.population:Array.from({length:AI_NETWORK_POPULATION},()=>LEARN.randomPolicy(rand)),results=[];for(let index=0;index<base.length;index++){if(!aiTraining.running||token!==aiLoopToken)return;const policy=base[index];let trials;try{trials=await v24Evaluate(policy,token)}catch{return}const result={};['fitness','days','population','births','deaths','starvationDeaths','satisfaction','money','lineageGeneration','adultDescendants','averagePopulation','minPopulation','peakPopulation','viableCouples','foodPerPerson','childRatio','workingAdultRatio','pregnancyStarts','marriages','housedCouples'].forEach(key=>result[key]=v21Average(trials,key));result.worstDays=Math.min(...trials.map(item=>item.days));result.worstBirths=Math.min(...trials.map(item=>item.births));result.worstPopulation=Math.min(...trials.map(item=>item.population));result.worstBirths=Math.min(...trials.map(item=>item.births));result.worstPregnancyStarts=Math.min(...trials.map(item=>item.pregnancyStarts));result.worstMarriages=Math.min(...trials.map(item=>item.marriages));result.worstViableCouples=Math.min(...trials.map(item=>item.viableCouples));result.fitness=(result.worstPopulation>0&&result.worstDays>=AI_HORIZON_DAYS?1e18:0)+result.worstDays*1e12+result.worstBirths*1e10+result.worstPregnancyStarts*1e9+result.worstMarriages*1e8+result.worstViableCouples*1e7+Math.min(result.population,40)*1e6-Math.max(0,result.peakPopulation-40)*1e8;results.push({policy,result});await new Promise(resolve=>setTimeout(resolve,0))}if(!aiTraining.running||token!==aiLoopToken)return;results.sort((a,b)=>b.result.fitness-a.result.fitness);const winner=results[0],improved=!aiTraining.best||winner.result.fitness>aiTraining.best.result.fitness;if(improved){aiTraining.best=winner;aiTraining.logs.unshift({stamp:`第${generation}代`,message:`新纪录：${Math.round(winner.result.days)}天 · ${winner.result.lineageGeneration.toFixed(1)}代 · 出生${winner.result.births.toFixed(1)} · 最终${winner.result.population.toFixed(1)}人`})}aiTraining.generation=generation;aiTraining.history.unshift({generation,improved,winnerDays:winner.result.days,winnerPopulation:winner.result.population,winnerLineageGeneration:winner.result.lineageGeneration,winnerAdultDescendants:winner.result.adultDescendants,winnerBirths:winner.result.births,winnerDeaths:winner.result.deaths,winnerStarvationDeaths:winner.result.starvationDeaths,winnerSatisfaction:winner.result.satisfaction,winnerAveragePopulation:winner.result.averagePopulation,winnerMinPopulation:winner.result.minPopulation,winnerViableCouples:winner.result.viableCouples,winnerPeakPopulation:winner.result.peakPopulation,winnerFoodPerPerson:winner.result.foodPerPerson,winnerChildRatio:winner.result.childRatio,winnerWorkingAdultRatio:winner.result.workingAdultRatio,winnerWorstDays:winner.result.worstDays,winnerWorstBirths:winner.result.worstBirths,winnerWorstPopulation:winner.result.worstPopulation,averageDays:v21Average(results.map(x=>x.result),'days'),averagePopulation:v21Average(results.map(x=>x.result),'population'),averageBirths:v21Average(results.map(x=>x.result),'births')});const elites=results.slice(0,12).map(x=>x.policy);aiTraining.population=elites.slice();while(aiTraining.population.length<AI_NETWORK_POPULATION){const a=random(elites),child=Math.random()<.8?LEARN.mutate(a):LEARN.mutate(LEARN.crossover(a,random(elites)));aiTraining.population.push(child)}aiSaveTraining();renderAITraining();if(repeat)setTimeout(()=>{if(token===aiLoopToken)aiRunGeneration()},30)};
  startAITraining=function(){if(aiTraining.running)return;aiTraining.running=true;aiLoopToken++;aiTraining.logs.unshift({stamp:`第${aiTraining.generation+1}代`,message:'开始训练动作策略网络'});renderAITraining();aiRunGeneration()};
  pauseAITraining=function(){if(!aiTraining.running)return;aiTraining.running=false;aiLoopToken++;v24StopWorker();aiSaveTraining();renderAITraining()};
  resetAITraining=function(){if(!window.confirm('确定清除V25动作策略的全部本地训练吗？游戏存档不会受影响。'))return;aiLoopToken++;v24StopWorker();aiTraining=v21Empty(true);localStorage.removeItem(V21_KEY);publishedAI=null;renderAITraining();renderAIQuickButton()};
  saveAIPolicyFile=async function(){if(!aiTraining.best)return toast('请先在本机训练出可用的动作策略');const best={...aiTraining.best};delete best.published;const policy={version:2,trainingVersion:25,publishedAt:new Date().toISOString(),generation:aiTraining.generation,source:'local-action-policy-evolution',best};try{const response=await fetch('/api/ai-policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(policy)});if(!response.ok)throw Error(response.status);publishedAI=policy;aiTraining.publishedBestFitness=best.result?.fitness??null;aiTraining.publishedAtGeneration=aiTraining.generation;aiSaveTraining();toast(`第 ${aiTraining.generation} 代当前最佳策略已保存`);renderAITraining()}catch{toast('无法写入策略文件：请使用 node server.js 启动本地训练服务器')}};
  renderAITraining=function(){const panel=$('aiTrainingPanel');if(!panel)return;const result=aiTraining.best?.result,history=aiTraining.history||[];panel.innerHTML=`<div class="ai-hero"><small>${aiTraining.running?'动作策略正在进化':'训练已暂停'}</small><b>${result?`最佳 ${Math.round(result.days)} 天 · 延续 ${result.lineageGeneration.toFixed(1)} 代`:'尚无V25训练结果'}</b><span>网络从全部合法动作中自行选择人物、配偶、岗位、住宅与消费</span></div><div class="ai-controls"><button id="aiTrainToggle" class="primary">${aiTraining.running?'暂停训练':'开始／继续训练'}</button><button id="aiTakeover" ${result?'':'disabled'}>${aiTraining.takeover?'停止接管':'最佳AI接管游戏'}</button><button id="aiSingleGeneration" ${aiTraining.running?'disabled':''}>只训练一代</button><button id="aiReset">清除训练</button><button id="aiExport" ${!aiTraining.best?'disabled':''}>${aiTraining.best&&aiTraining.publishedBestFitness===aiTraining.best.result?.fitness?'再次保存当前最佳':'保存当前最佳到策略文件'}</button></div><section class="ai-parameters"><b>动作策略网络 V25</b><span>${LEARN.ACTIONS.length} 类动作</span><span>${LEARN.FEATURES} 个状态特征</span><span>${LEARN.WEIGHTS} 个可训练权重</span><span>每代 ${AI_NETWORK_POPULATION} 个候选网络</span><span>${AI_TEST_WORLDS} 个固定世界</span><button id="copyAIReport" type="button" ${history.length?'':'disabled'}>复制训练诊断</button></section><div class="ai-metrics"><span><small>训练代数</small><b>${aiTraining.generation}</b></span><span><small>最终人口</small><b>${result?result.population.toFixed(1):'—'}</b></span><span><small>期间平均人口</small><b>${result?result.averagePopulation.toFixed(1):'—'}</b></span><span><small>最低人口</small><b>${result?result.minPopulation.toFixed(1):'—'}</b></span><span><small>可组成夫妻数</small><b>${result?result.viableCouples.toFixed(1):'—'}</b></span><span><small>人口峰值</small><b>${result?result.peakPopulation.toFixed(1):'—'}</b></span><span><small>人均食物</small><b>${result?result.foodPerPerson.toFixed(1):'—'}</b></span><span><small>延续世代</small><b>${result?result.lineageGeneration.toFixed(1):'—'}</b></span><span><small>成年后代</small><b>${result?result.adultDescendants.toFixed(1):'—'}</b></span><span><small>累计出生</small><b>${result?result.births.toFixed(1):'—'}</b></span><span><small>饥饿死亡</small><b>${result?result.starvationDeaths.toFixed(1):'—'}</b></span></div><section class="ai-batches"><header><b>最近训练批次</b><small>${aiTraining.running?'实时更新中':'已暂停'}</small></header>${history.slice(0,10).map(row=>`<div class="ai-batch-row ${row.improved?'improved':''}"><b>第 ${row.generation} 代${row.improved?' ↑':''}</b><span>冠军 ${Math.round(row.winnerDays)}天 / ${row.winnerLineageGeneration.toFixed(1)}代 / 出生${row.winnerBirths.toFixed(1)}</span><small>平均 ${Math.round(row.averageDays)}天 / 出生${row.averageBirths.toFixed(1)}</small></div>`).join('')||'<div class="ai-batch-empty">开始训练后显示每代变化。</div>'}</section><div class="ai-log-card"><h3>关键进展</h3><div class="ai-log">${(aiTraining.logs||[]).slice(0,6).map(x=>`<p><time>${x.stamp}</time><span>${x.message}</span></p>`).join('')||'<p class="ai-empty">暂无记录</p>'}</div></div>`;$('aiTrainToggle').onclick=aiTraining.running?pauseAITraining:startAITraining;$('aiTakeover').onclick=toggleAITakeover;$('aiSingleGeneration').onclick=async()=>{if(aiTraining.running)return;aiTraining.running=true;aiLoopToken++;renderAITraining();await aiRunGeneration(false);pauseAITraining()};$('aiReset').onclick=resetAITraining;$('aiExport').onclick=saveAIPolicyFile;$('copyAIReport').onclick=copyAITrainingReport};
  function v21Related(a,b){const pa=a.parentIds||[],pb=b.parentIds||[];return pa.includes(b.id)||pb.includes(a.id)||pa.some(id=>pb.includes(id))}
  function v21LiveState(){const food=state.floors.reduce((n,f)=>n+(f.stock?.vegetables||0)+(f.stock?.meat||0)+(f.stock?.cannedVegetables||0)+(f.stock?.cannedMeat||0),0),homes=state.floors.filter(isPrivateHome),freeBeds=homes.reduce((n,h)=>n+Math.max(0,housingCapacity(h)-(h.residents||[]).length),0);return{people:state.people,day:Math.floor((simulationNow()-state.createdAt)/DAY_MS),money:state.money,food,children:state.people.filter(p=>p.age<18).length,homes:homes.length,freeBeds,gardens:state.floors.filter(f=>f.type==='garden').length,foodWorkers:state.floors.filter(f=>['garden','farm','market'].includes(f.type)).reduce((n,f)=>n+f.workerIds.length,0),medicalWorkers:state.floors.filter(f=>['clinic','maternity'].includes(f.type)).reduce((n,f)=>n+f.workerIds.length,0),teachers:state.floors.filter(f=>['primary','middle','school','university'].includes(f.type)&&f.teacherId).length,satisfaction:state.people.length?state.people.reduce((n,p)=>n+p.satisfaction,0)/state.people.length:0}}
  function v21Candidates(){const s=v21LiveState(),list=[{type:'wait',features:LEARN.vector(s)}],build=['garden','farm','market','clinic','maternity','park','rental'];for(const type of build)if(state.money>=ROOMS[type].cost)list.push({type:`build${type[0].toUpperCase()+type.slice(1)}`,roomType:type,features:LEARN.vector(s,null,null,{urgent:type==='maternity'&&state.people.some(p=>p.pregnancy)})});const city=state.floors.find(f=>f.type==='cityhall');for(const person of state.people.filter(p=>p.age>16&&!p.sick)){if(city&&!city.mayorId)list.push({type:'setMayor',person,features:LEARN.vector(s,person)});for(const floor of state.floors.filter(f=>!['cityhall','park','primary','middle','school','university','barber'].includes(f.type)&&f.workerIds.length<roomCapacity(f)&&meetsWorkerSkill(person,f)&&!workerFloor(person.id)))list.push({type:'assignJob',person,floor,features:LEARN.vector(s,person,null,{urgent:['garden','farm'].includes(floor.type)})})}const singles=state.people.filter(p=>p.age>=20&&p.age<=40&&!p.spouseId&&!p.sick);for(let i=0;i<singles.length;i++)for(let j=i+1;j<singles.length;j++){const a=singles[i],b=singles[j];if(a.gender!==b.gender&&!v21Related(a,b))list.push({type:'marry',person:a,target:b,features:LEARN.vector(s,a,b)})}for(const wife of state.people.filter(p=>p.gender==='女'&&isFertileAge(p)&&p.spouseId&&!p.pregnancy)){const husband=residentById(wife.spouseId),home=sharedPrivateHome(wife,husband);if(husband&&isFertileAge(husband)&&home&&home.residents.length<housingCapacity(home))list.push({type:'conceive',person:wife,target:husband,home,features:LEARN.vector(s,wife,husband,{value:(housingCapacity(home)-home.residents.length)/6})})}for(const person of state.people.filter(p=>!residentHome(p)&&spendableMoney(p)>=ROOMS.oldApartment.cost))list.push({type:'buyHome',person,roomType:'oldApartment',features:LEARN.vector(s,person,null,{urgent:Boolean(person.spouseId)})});return list}
  function v21Execute(a){if(!a||a.type==='wait')return;switch(a.type){case'buildGarden':case'buildFarm':case'buildMarket':case'buildClinic':case'buildMaternity':case'buildPark':case'buildRental':aiAddRoom(a.roomType);break;case'setMayor':{const city=state.floors.find(f=>f.type==='cityhall');if(city){removePersonAssignments(a.person.id,city);city.mayorId=a.person.id}}break;case'assignJob':removePersonAssignments(a.person.id,a.floor);a.floor.workerIds.push(a.person.id);a.floor.cycleStartedAt=simulationNow();break;case'marry':a.person.spouseId=a.target.id;a.target.spouseId=a.person.id;shareMarriageHomeOwnership(a.person,a.target);aiLog(`策略促成 ${a.person.name} 与 ${a.target.name} 结婚`);break;case'buyHome':purchaseProperty(a.person.id,a.roomType);break;case'conceive':a.person.pregnancy={fatherId:a.target.id,dueAt:simulationNow()+PREGNANCY_MS,deliveryWarned:false,laborWarned:false};celebrate(state.people.map(p=>p.id),'新生命即将到来！');break}save();render()}
  aiLiveDecision=function(){if(!aiTraining.takeover||Number.isFinite(state.pausedAt))return;const policy=activeAIBest()?.policy;if(!LEARN.valid(policy))return;for(let i=0;i<4;i++){const action=LEARN.choose(policy,v21Candidates());if(!action||action.type==='wait')break;v21Execute(action)}};
  toggleAITakeover=function(){if(!LEARN.valid(activeAIBest()?.policy))return toast('暂时没有可用的V25动作策略');aiTraining.takeover=!aiTraining.takeover;aiSaveTraining();renderAIQuickButton();renderAITraining();if(aiTraining.takeover)aiLiveDecision()};
  quickAIToggle=function(){if(aiTraining.takeover)return toggleAITakeover();if(Number.isFinite(state.pausedAt))return toast('游戏当前已暂停，请先点击继续');if(!LEARN.valid(activeAIBest()?.policy))return toast('请先在AI训练页至少完成一代训练');aiTraining.takeover=true;aiSaveTraining();renderAIQuickButton();aiLiveDecision()};
  aiMayorRotation=aiFamilyDecision=aiFoodDecision=aiPrepareWorkforce=aiEducationDecision=aiLifeAdminDecision=aiServiceDecision=function(){};
  buildAITrainingReport=function(){const r=aiTraining.best?.result,h=(aiTraining.history||[]).slice(0,20).reverse(),lines=['# AI训练诊断','',`- 训练版本：V25（动作策略网络）`,`- 当前代数：${aiTraining.generation}`,`- 动作类型：${LEARN.ACTIONS.length}；状态特征：${LEARN.FEATURES}；可训练权重：${LEARN.WEIGHTS}；候选网络：${AI_NETWORK_POPULATION}/代`,`- 当前最佳：${r?`${Math.round(r.days)}天，最终${r.population.toFixed(1)}人，延续${r.lineageGeneration.toFixed(1)}代，成年后代${r.adultDescendants.toFixed(1)}，出生${r.births.toFixed(1)}，饥饿死亡${r.starvationDeaths.toFixed(1)}，平均人口${r.averagePopulation.toFixed(1)}，最低人口${r.minPopulation.toFixed(1)}，可组成夫妻${r.viableCouples.toFixed(1)}，人口峰值${r.peakPopulation.toFixed(1)}，人均食物${r.foodPerPerson.toFixed(1)}，最差世界${Math.round(r.worstDays)}天/出生${r.worstBirths.toFixed(1)}/最终${r.worstPopulation.toFixed(1)}人`:'无'}`,'','| 代数 | 破纪录 | 冠军天数 | 延续世代 | 成年后代 | 出生 | 最终人口 | 饥饿死亡 | 最低人口 | 可组成夫妻 | 平均天数 | 平均出生 |','|---:|:---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|'];h.forEach(x=>lines.push(`| ${x.generation} | ${x.improved?'是':'否'} | ${Math.round(x.winnerDays)} | ${x.winnerLineageGeneration.toFixed(1)} | ${x.winnerAdultDescendants.toFixed(1)} | ${x.winnerBirths.toFixed(1)} | ${x.winnerPopulation.toFixed(1)} | ${x.winnerStarvationDeaths.toFixed(1)} | ${x.winnerMinPopulation.toFixed(1)} | ${x.winnerViableCouples.toFixed(1)} | ${Math.round(x.averageDays)} | ${x.averageBirths.toFixed(1)} |`));return lines.join('\n')};
  setInterval(aiLiveDecision,5000);
