  document.querySelectorAll('nav button').forEach(button=>button.onclick=()=>showView(button.dataset.view));$('goBuild').onclick=()=>showView('build');$('quickAI').onclick=quickAIToggle;$('pauseGame').onclick=togglePause;$('closeSheet').onclick=closeSheets;$('closeRoomSheet').onclick=closeSheets;$('backdrop').onclick=()=>{if(!$('inheritanceNotice').hidden||!$('deathNotice').hidden||!$('gameOverNotice').hidden)return;closeSheets()};$('confirmDeath').onclick=confirmDeath;$('inheritHome').onclick=inheritPendingHome;$('passInheritance').onclick=passPendingInheritance;$('sellInheritedHome').onclick=()=>sellInheritanceHome();$('viewAITraining').onclick=()=>{$('gameOverNotice').hidden=true;$('backdrop').classList.remove('show');showView('ai')};$('restartAfterGameOver').onclick=()=>{localStorage.removeItem(SAVE_KEY);const url=new URL(location.href);url.searchParams.set('reset',Date.now());location.replace(url)};
